#include <windows.h>
#include <winternl.h>
#include <stdio.h>

typedef NTSTATUS (NTAPI *LdrLoadDllFn)(PCWSTR, PULONG, PUNICODE_STRING,
    PVOID*);
typedef NTSTATUS (NTAPI *LdrUnloadDllFn)(PVOID);

int main() {
    HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
    auto load = reinterpret_cast<LdrLoadDllFn>(
        GetProcAddress(ntdll, "LdrLoadDll"));
    auto unload = reinterpret_cast<LdrUnloadDllFn>(
        GetProcAddress(ntdll, "LdrUnloadDll"));
    if (load == nullptr || unload == nullptr) {
        return 1;
    }

    UNICODE_STRING name = {};
    RtlInitUnicodeString(&name, L"kernel32.dll");
    PVOID module = nullptr;
    NTSTATUS status = load(nullptr, nullptr, &name, &module);
    if (status >= 0 && module != nullptr) {
        unload(module);
    }
    return 0;
}

