extern "C" NTSTATUS NTAPI NtAdjustPrivilegesToken(HANDLE, BOOLEAN,
    PTOKEN_PRIVILEGES, ULONG, PTOKEN_PRIVILEGES, PULONG);

int main() {
    HANDLE token = nullptr;
    if (!OpenProcessToken(GetCurrentProcess(),
            TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, &token)) {
        return 1;
    }

    LUID luid = {};
    LookupPrivilegeValueA(nullptr, SE_CHANGE_NOTIFY_NAME, &luid);

    TOKEN_PRIVILEGES privileges = {};
    privileges.PrivilegeCount = 1;
    privileges.Privileges[0].Luid = luid;
    privileges.Privileges[0].Attributes = 0;

    TOKEN_PRIVILEGES previous = {};
    ULONG length = sizeof(previous);
    NTSTATUS status = NtAdjustPrivilegesToken(token, FALSE, &privileges,
        sizeof(previous), &previous, &length);
    if (status >= 0) {
        NtAdjustPrivilegesToken(token, FALSE, &previous, 0, nullptr,
            nullptr);
    }

    CloseHandle(token);
    return 0;
}

