    POBJECT_ATTRIBUTES, PIO_STATUS_BLOCK, PLARGE_INTEGER, ULONG, ULONG,
    ULONG, ULONG, PVOID, ULONG);
extern "C" NTSTATUS NTAPI NtQueryDirectoryFile(HANDLE, HANDLE,
    PIO_APC_ROUTINE, PVOID, PIO_STATUS_BLOCK, PVOID, ULONG, ULONG, BOOLEAN,
    PUNICODE_STRING, BOOLEAN);

int main() {
    UNICODE_STRING path = {};
    RtlInitUnicodeString(&path, L"\\??\\C:\\Windows");
    OBJECT_ATTRIBUTES attributes = {};
    InitializeObjectAttributes(&attributes, &path,
        OBJ_CASE_INSENSITIVE, nullptr, nullptr);

    IO_STATUS_BLOCK status_block = {};
    HANDLE directory = nullptr;
    NTSTATUS status = NtCreateFile(&directory,
        FILE_LIST_DIRECTORY | SYNCHRONIZE, &attributes, &status_block,
        nullptr, FILE_ATTRIBUTE_NORMAL,
        FILE_SHARE_READ | FILE_SHARE_WRITE, FILE_OPEN,
        FILE_DIRECTORY_FILE | FILE_SYNCHRONOUS_IO_NONALERT, nullptr, 0);
    if (status < 0) {
        return 1;
    }

    char buffer[1024] = {};
    status = NtQueryDirectoryFile(directory, nullptr, nullptr, nullptr,
        &status_block, buffer, sizeof(buffer),
        static_cast<FILE_INFORMATION_CLASS>(1), TRUE, nullptr, TRUE);
    if (status >= 0) {
        printf("Read one directory entry.\n");
    }

    NtClose(directory);
    return 0;
}

