extern "C" NTSTATUS NTAPI NtMapViewOfSection(HANDLE, HANDLE, PVOID*,
    ULONG_PTR, SIZE_T, PLARGE_INTEGER, PSIZE_T, ULONG, ULONG, ULONG);
extern "C" NTSTATUS NTAPI NtUnmapViewOfSection(HANDLE, PVOID);

int main() {
    LARGE_INTEGER maximum = {};
    maximum.QuadPart = 4096;

    HANDLE section = nullptr;
    NTSTATUS status = NtCreateSection(&section, SECTION_ALL_ACCESS, nullptr,
        &maximum, PAGE_READWRITE, SEC_COMMIT, nullptr);
    if (status < 0) {
        return 1;
    }

    PVOID base = nullptr;
    SIZE_T view_size = 0;
    status = NtMapViewOfSection(section, GetCurrentProcess(), &base, 0, 0,
        nullptr, &view_size, ViewUnmap, 0, PAGE_READWRITE);
    if (status >= 0) {
        memcpy(base, "example", 8);
        NtUnmapViewOfSection(GetCurrentProcess(), base);
    }

    NtClose(section);
    return 0;
}

#include <windows.h>
#include <winternl.h>
#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtWaitForMultipleObjects(ULONG, HANDLE[], ULONG,
    BOOLEAN, PLARGE_INTEGER);

int main() {
    HANDLE events[2] = {
        CreateEventW(nullptr, TRUE, FALSE, nullptr),
        CreateEventW(nullptr, TRUE, FALSE, nullptr)
    };
    if (events[0] == nullptr || events[1] == nullptr) {
        return 1;
    }

    SetEvent(events[1]);
    LARGE_INTEGER timeout = {};
    timeout.QuadPart = -1000000; // 100 ms.
    NTSTATUS status = NtWaitForMultipleObjects(2, events, 1, FALSE,
        &timeout);
    printf("Wait status: 0x%08lx\n", status);

    NtClose(events[0]);
    NtClose(events[1]);
    return 0;
}

