#include <stdio.h>

#pragma comment(lib, "ntdll.lib")

extern "C" NTSTATUS NTAPI NtWriteVirtualMemory(HANDLE, PVOID, PVOID, SIZE_T,
    PSIZE_T);

int main() {
    char destination[32] = {};
    const char source[] = "example";
    SIZE_T written = 0;

    NTSTATUS status = NtWriteVirtualMemory(GetCurrentProcess(), destination,
        const_cast<char*>(source), sizeof(source), &written);
    if (status >= 0) {
        printf("Wrote %zu bytes.\n", written);
    }
    return 0;
}

